// In-Memory LRU Cache Engine
// Starter Scaffolding Template

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.atomic.AtomicLong;

public class LruCacheEngineDemo {

    public static class LruCache<K, V> extends LinkedHashMap<K, V> {
        private final int maxCapacity;
        private final AtomicLong hits = new AtomicLong();
        private final AtomicLong misses = new AtomicLong();
        private final AtomicLong evictions = new AtomicLong();

        public LruCache(int maxCapacity) {
            super(maxCapacity, 0.75f, true);
            this.maxCapacity = maxCapacity;
        }

        @Override
        protected boolean removeEldestEntry(Map.Entry<K, V> eldest) {
            boolean shouldEvict = size() > maxCapacity;
            if (shouldEvict) {
                evictions.incrementAndGet();
            }
            return shouldEvict;
        }

        public synchronized Optional<V> getOptional(K key) {
            V val = super.get(key);
            if (val != null) {
                hits.incrementAndGet();
                return Optional.of(val);
            } else {
                misses.incrementAndGet();
                return Optional.empty();
            }
        }

        public synchronized void putValue(K key, V value) {
            if (key == null || value == null) {
                throw new IllegalArgumentException("Key and value cannot be null");
            }
            super.put(key, value);
        }

        public double getHitRatio() {
            long h = hits.get();
            long total = h + misses.get();
            return total == 0 ? 0.0 : ((double) h / total) * 100.0;
        }
    }

    public static void main(String[] args) {
        System.out.println("=== In-Memory LRU Cache Engine ===");
        LruCache<String, String> cache = new LruCache<>(3);
        cache.putValue("k1", "v1");
        cache.putValue("k2", "v2");
        cache.putValue("k3", "v3");
        System.out.println("Cache size: " + cache.size());
    }
}

