import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.atomic.AtomicLong;

public class LruCacheDemo {

    public static class LruCache<K, V> extends LinkedHashMap<K, V> {
        private final int maxCapacity;
        private final AtomicLong hits = new AtomicLong();
        private final AtomicLong misses = new AtomicLong();
        private final AtomicLong evictions = new AtomicLong();

        public LruCache(int maxCapacity) {
            super(maxCapacity, 0.75f, true);
            this.maxCapacity = maxCapacity;
        }

        @Override
        protected boolean removeEldestEntry(Map.Entry<K, V> eldest) {
            boolean shouldEvict = size() > maxCapacity;
            if (shouldEvict) {
                evictions.incrementAndGet();
            }
            return shouldEvict;
        }

        public synchronized Optional<V> getOptional(K key) {
            V val = super.get(key);
            if (val != null) {
                hits.incrementAndGet();
                return Optional.of(val);
            }
            misses.incrementAndGet();
            return Optional.empty();
        }

        public synchronized void putValue(K key, V value) {
            if (key == null || value == null) {
                throw new IllegalArgumentException("Null key/value rejected");
            }
            super.put(key, value);
        }

        public double getHitRatio() {
            long h = hits.get();
            long total = h + misses.get();
            return total == 0 ? 0.0 : ((double) h / total) * 100.0;
        }

        public long getEvictionCount() {
            return evictions.get();
        }
    }

    public static void main(String[] args) {
        LruCache<String, String> cache = new LruCache<>(3);
        cache.putValue("A", "Alpha");
        cache.putValue("B", "Beta");
        cache.putValue("C", "Gamma");
        System.out.println("Cache keys after 3 puts: " + cache.keySet());

        // Access 'A' to promote it to MRU
        cache.getOptional("A");
        System.out.println("Accessed 'A'. Next insertion should evict 'B'.");

        // Insert 'D' -> capacity exceeded, evicts 'B'
        cache.putValue("D", "Delta");
        System.out.println("Cache keys after adding 'D': " + cache.keySet());
        System.out.println("Is 'B' present? " + cache.getOptional("B").isPresent());
        System.out.println("Evictions count: " + cache.getEvictionCount());
        System.out.printf("Hit Ratio: %.1f%%\n", cache.getHitRatio());
    }
}
