import java.util.Map;

public class SnapshotSupplier {
    public static <K, V> Map<K, V> getSafeSnapshot(Map<K, V> synchronizedCache) {
        if (synchronizedCache == null) return Map.of();
        synchronized (synchronizedCache) {
            return Map.copyOf(synchronizedCache);
        }
    }
}

