import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;

public class EvictionTracker<K> {
    private final ArrayDeque<K> history = new ArrayDeque<>();

    public synchronized void recordEviction(K key) {
        if (key != null) {
            history.addFirst(key);
        }
    }

    public synchronized List<K> getRecentEvictions(int count) {
        List<K> result = new ArrayList<>();
        int n = 0;
        for (K key : history) {
            if (n++ >= count) break;
            result.add(key);
        }
        return List.copyOf(result);
    }
}
